// Control unit is obtained by modifying the solution to Prob. 8.24.// Datapath is implemented with a structural  HDL model and IC components.// LOAD condition for 74194: s1 = 1, s0 = 1// SHIFT condition: s1 = 0, s0 = 1// NO CHANGE condition: s1 = 0, s0 = 0module Supp_9_17_Par_Mult # (parameter dp_width = 4) (  output 	[2*dp_width - 1: 0] 	Product,  output							Ready,  input 	[dp_width - 1: 0] 			Multiplicand, Multiplier,  input 								Start, clock, reset_b, VCC, GND);  wire Load_regs, Incr_P, Add_regs, Shift_regs, Done, Q0;  Controller M0 (    Ready, Load_regs, Incr_P, Add_regs, Shift_regs, Start, Done, Q0,     clock, reset_b);  Datapath M1(Product, Q0, Done, Multiplicand, Multiplier,  Start, Load_regs, Incr_P, Add_regs, Shift_regs, clock, reset_b, VCC, GND);	endmodulemodule Controller (  output Ready,  output reg Load_regs, Incr_P, Add_regs, Shift_regs,     input Start, Done, Q0, clock, reset_b);  parameter	S_idle =	3'b001, 		// one-hot code        			S_add = 3'b010, 		       			S_shift = 3'b100;  reg	[2: 0]	state, next_state;		// sized for one-hot  assign		Ready = (state == S_idle);	    always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Done) begin    next_state = S_idle;    Load_regs = 0;    Incr_P = 0;    Add_regs = 0;    Shift_regs = 0;    case (state)      S_idle:	if (Start) begin next_state = S_add; Load_regs = 1; end      S_add:	begin next_state = S_shift; Incr_P = 1; if (Q0) Add_regs = 1; end      S_shift:	begin 		  		  Shift_regs = 1; 		  		  if (Done) next_state = S_idle; 		  		  else next_state = S_add;    end      default:	next_state = S_idle;    endcase  endendmodulemodule Datapath #(parameter dp_width = 4, BC_size = 3) (  output [2*dp_width - 1: 0] Product, output Q0, output Done,  input [dp_width - 1: 0] Multiplicand, Multiplier,  input Start, Load_regs, Incr_P, Add_regs, Shift_regs, clock, clear, VCC, GND);  wire C;  wire Cout, Sum3, Sum2, Sum1, Sum0, P3, P2, P1, P0, A3, A2, A1, A0;  wire Q3, Q2, Q1;  wire [dp_width -1: 0] A = {A3, A2, A1, A0};  wire [dp_width -1: 0] Q = {Q3, Q2, Q1, Q0};  assign Product = {C, A, Q};   wire [ BC_size -1: 0] P = {P3, P2, P1, P0};// Registers must be controlled separately to execute add and shift operations correctly.// LOAD condition for 74194: s1 = 1, s0 = 1// SHIFT condition: s1 = 0, s0 = 1// NO CHANGE condition: s1 = 0, s0 = 0    wire B3 = Multiplicand[3];		// Data word to adder  wire B2 = Multiplicand[2];    wire B1 = Multiplicand[1];    wire B0 = Multiplicand[0];  wire Q3_in = Multiplier[3];  wire Q2_in = Multiplier[2];  wire Q1_in = Multiplier[1];  wire Q0_in = Multiplier[0];  assign Done = ({P3, P2, P1, P0} == dp_width);		// Counts bits of multiplier  wire s1A = Load_regs || Add_regs;			// Controls for A register  wire s0A = Load_regs || Add_regs || Shift_regs;  wire s0Q = Load_regs || Shift_regs;			// Controls for Q register  wire s1Q = Load_regs;   wire Pout;						// Unused  wire clr_P = clear && ~Load_regs;  Flip_flop_7474 	M0_C (C, Cout, clock, VCC, clr_P);   Adder_7483 	M1 (Sum3, Sum2, Sum1, Sum0, Cout, A3, A2, A1, A0, B3, B2, B1, B0, GND, VCC, GND);  Counter_74161 	M3_P (P3, P2, P1, P0, Pout, GND, GND, GND, GND, Incr_P, Incr_P, VCC, clock, clr_P);  Reg_74194	M4_A (A3, A2, A1, A0, Sum3, Sum2, Sum1, Sum0, C, GND, s1A, s0A, clock, clr_P);  Reg_74194	M5_Q (Q3, Q2, Q1, Q0, Q3_in, Q2_in, Q1_in, Q0_in, A0, GND, s1Q, s0Q, clock, clear);endmodulemodule t_Supp_9_17_Par_Mult;  parameter			dp_width = 4;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire				Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 				Start, clock, reset_b;  integer				Exp_Value;  reg				Error;  supply0			GND;  supply1			VCC;  Supp_11_17_Par_Mult M0 (Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b, VCC, GND);  wire [dp_width -1: 0] sum = {M0.M1.Sum3, M0.M1.Sum2, M0.M1.Sum1, M0.M1.Sum0};  initial #115000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  always @ (negedge Start) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  always @ (posedge Ready) begin    # 1 Error <= (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;    repeat (32) #10 begin        Start = 1;        #10 Start = 0;        repeat (32) begin          Start = 1;          #10 Start = 0;                    #100 Multiplicand = Multiplicand + 1;        end      Multiplier = Multiplier + 1;    end  endendmodulemodule Flip_flop_7474 (output reg Q, input D, CLK, preset, clear); always @ (posedge CLK, negedge preset , negedge clear)if (!preset)     	Q <= 1'b1;else if (!clear) 	Q <= 1'b0;else 	Q <= D;endmodulemodule Adder_7483 (  output S4, S3, S2, S1, C4,  input A4, A3, A2, A1, B4, B3, B2, B1, C0, VCC, GND);// Note: connect VCC and GND to supply1 and supply0 in the test bench  wire [4: 1] sum;  wire [4: 1] A = {A4, A3, A2, A1};  wire [4: 1] B = {B4, B3, B2, B1};  assign S4 = sum[4];  assign S3 = sum[3];  assign S2 = sum[2];  assign S1 = sum[1];  assign {C4, sum} = A + B + C0;endmodulemodule Counter_74161 (  output  	QD, QC, QB, QA,		// Data output  output 		COUT,			// Output carry  input	 	D, C, B, A,		// Data input   input 		P, T, 			// Active high to count		L, 			// Active low to load		CK, 			// Positive edge sensitive		CLR			// Active low to clear);reg [3: 0] A_count;assign QD = A_count[3];assign QC = A_count[2];assign QB = A_count[1];assign QA = A_count[0];assign COUT = ((P == 1) && (T == 1) && (L == 1) && (A_count == 4'b1111));always @ (posedge CK, negedge CLR)if (CLR == 0) 			A_count <= 4'b0000;else if (L == 0)			A_count <= {D, C, B, A};else if ((P == 1) && (T == 1)) 	A_count <= A_count + 1'b1;else 				A_count <= A_count;	// redundant statementendmodulemodule Reg_74194 (  output reg QA, QB, QC, QD,  input A, B, C, D, SIR, SIL, s1, s0, CK, CLR);  always @ (posedge CK, negedge CLR)    if (!CLR) {QA, QB, QC, QD} <= 4'b0;    else case ({s1, s0})      2'b00:	{QA, QB, QC, QD} <= {QA, QB, QC, QD};      2'b01:	{QA, QB, QC, QD} <= {SIR, QA, QB, QC};      2'b10:	{QA, QB, QC, QD} <= {QB, QC, QD, SIL};      2'b11:	{QA, QB, QC, QD} <= {A, B, C, D};    endcaseendmodule